import { PivotSheet, DataCell } from '@antv/s2';
import { Line } from '@antv/g';

class MiniChartDataCell extends DataCell {
  drawTextShape() {
    super.drawTextShape();

    const meta = this.getMeta();
    const data = meta.data;

    if (data && data.trend && Array.isArray(data.trend)) {
      this.drawMiniChart(data.trend);
    }
  }

  drawMiniChart(trendData) {
    const bbox = this.getBBoxByType();
    const chartWidth = bbox.width - 20;
    const chartHeight = 20;
    const startX = bbox.x + 10;
    const startY = bbox.y + bbox.height - 25;

    const max = Math.max(...trendData);
    const min = Math.min(...trendData);
    const range = max - min || 1;

    // 绘制趋势线
    for (let i = 0; i < trendData.length - 1; i++) {
      const x1 = startX + (i / (trendData.length - 1)) * chartWidth;
      const y1 = startY + chartHeight - ((trendData[i] - min) / range) * chartHeight;
      const x2 = startX + ((i + 1) / (trendData.length - 1)) * chartWidth;
      const y2 = startY + chartHeight - ((trendData[i + 1] - min) / range) * chartHeight;

      this.appendChild(
        new Line({
          style: {
            x1,
            y1,
            x2,
            y2,
            stroke: '#1890ff',
            lineWidth: 2,
          },
        })
      );
    }
  }
}

