import { PivotSheet, DataCell } from '@antv/s2';
import { Chart } from '@antv/g2';

class G2ChartDataCell extends DataCell {
  drawTextShape() {
    super.drawTextShape();

    const meta = this.getMeta();
    const data = meta.data;

    if (data && data.performance && Array.isArray(data.performance)) {
      this.drawG2Chart(data.performance);
    }
  }

  drawG2Chart(performanceData) {
    const bbox = this.getBBoxByType();
    const chartContainer = document.createElement('div');
    chartContainer.style.width = `${bbox.width - 20}px`;
    chartContainer.style.height = '30px';
    chartContainer.style.position = 'absolute';
    chartContainer.style.left = `${bbox.x + 10}px`;
    chartContainer.style.top = `${bbox.y + bbox.height - 35}px`;
    chartContainer.style.pointerEvents = 'none';

    document.body.appendChild(chartContainer);

    const chartData = performanceData.map((value, index) => ({
      month: `M${index + 1}`,
      value,
    }));

    const chart = new Chart({
      container: chartContainer,
      autoFit: true,
      height: 30,
      padding: [2, 2, 2, 2],
    });

    chart.data(chartData);
    chart.scale('value', { nice: true });
    chart.axis(false);
    chart.legend(false);
    chart.tooltip(false);

    chart
      .interval()
      .position('month*value')
      .color('#1890ff')
      .size(3);

    chart.render();
  }
}

