class CustomRowHeaderCell extends RowCell {
  drawTextShape() {
    super.drawTextShape();

    const meta = this.getMeta();
    const level = meta.level;
    const value = meta.value;
    const bbox = this.getBBoxByType();

    // 为不同层级添加自定义标识
    if (level === 0) { // department层级
      this.drawDepartmentIcon(value, bbox);
    } else if (level === 1) { // team层级
      this.drawTeamBadge(value, bbox);
    }
  }

  drawDepartmentIcon(department, bbox) {
    const iconMap = {
      '研发部': '🔧',
      '产品部': '📱',
      '市场部': '📈'
    };

    const icon = iconMap[department] || '🏢';

    this.appendChild(
      new GText({
        style: {
          x: bbox.x + 5,
          y: bbox.y + bbox.height / 2,
          text: icon,
          fontSize: 16,
          textAlign: 'left',
          textBaseline: 'middle',
        },
      })
    );
  }

  drawTeamBadge(team, bbox) {
    const badgeColors = {
      '前端组': '#52c41a',
      '后端组': '#1890ff',
      '设计组': '#fa8c16',
      '测试组': '#f5222d'
    };

    const color = badgeColors[team] || '#d9d9d9';

    this.appendChild(
      new GText({
        style: {
          x: bbox.x + 5,
          y: bbox.y + bbox.height / 2,
          text: '●',
          fontSize: 12,
          fill: color,
          textAlign: 'left',
          textBaseline: 'middle',
        },
      })
    );
  }
}

