import { PivotSheet, DataCell } from '@antv/s2';
import { Rect, Text as GText } from '@antv/g';

class CustomRendererDataCell extends DataCell {
  drawTextShape() {
    const meta = this.getMeta();
    const fieldValue = meta.fieldValue;
    const valueField = meta.valueField;

    if (valueField === 'progress') {
      this.drawProgressBar(fieldValue);
    } else if (valueField === 'budget') {
      this.drawBudgetText(fieldValue);
    } else {
      super.drawTextShape();
    }
  }

  drawProgressBar(progress) {
    const bbox = this.getBBoxByType();
    const barWidth = bbox.width - 20;
    const barHeight = 20;
    const progressWidth = (progress / 100) * barWidth;

    // 绘制进度条背景
    this.appendChild(
      new Rect({
        style: {
          x: bbox.x + 10,
          y: bbox.y + bbox.height / 2 - barHeight / 2,
          width: barWidth,
          height: barHeight,
          fill: '#f0f0f0',
          stroke: '#d9d9d9',
          lineWidth: 1,
          radius: 4,
        },
      })
    );

    // 绘制进度条填充
    const progressColor = progress >= 80 ? '#52c41a' : progress >= 60 ? '#faad14' : '#ff4d4f';
    this.appendChild(
      new Rect({
        style: {
          x: bbox.x + 10,
          y: bbox.y + bbox.height / 2 - barHeight / 2,
          width: progressWidth,
          height: barHeight,
          fill: progressColor,
          radius: 4,
        },
      })
    );

    // 绘制进度文字
    this.appendChild(
      new GText({
        style: {
          x: bbox.x + bbox.width / 2,
          y: bbox.y + bbox.height / 2,
          text: `${progress}%`,
          fontSize: 12,
          fill: '#000',
          textAlign: 'center',
          textBaseline: 'middle',
          fontWeight: 'bold',
        },
      })
    );
  }

  drawBudgetText(budget) {
    const bbox = this.getBBoxByType();
    const formattedBudget = `¥${Number(budget).toLocaleString()}`;

    // 绘制货币符号背景
    this.appendChild(
      new Rect({
        style: {
          x: bbox.x + 5,
          y: bbox.y + 5,
          width: bbox.width - 10,
          height: bbox.height - 10,
          fill: '#e6f7ff',
          stroke: '#91d5ff',
          lineWidth: 1,
          radius: 4,
        },
      })
    );

    // 绘制格式化后的金额
    this.appendChild(
      new GText({
        style: {
          x: bbox.x + bbox.width / 2,
          y: bbox.y + bbox.height / 2,
          text: formattedBudget,
          fontSize: 14,
          fill: '#1890ff',
          textAlign: 'center',
          textBaseline: 'middle',
          fontWeight: 'bold',
        },
      })
    );
  }
}

