// 自定义Hook：投资分析监听器
class InvestmentAnalysisHook {
  constructor(spreadsheet) {
    this.spreadsheet = spreadsheet;
    this.bindEvents();
  }

  bindEvents() {
    // 监听数据更新事件
    this.spreadsheet.on(S2Event.LAYOUT_AFTER_RENDER, () => {
      this.analyzeInvestmentData();
    });

    // 监听单元格点击事件
    this.spreadsheet.on(S2Event.DATA_CELL_CLICK, (event) => {
      const meta = event.target?.getMeta();
      if (meta?.valueField === 'roi') {
        this.generateRiskAssessment(meta);
      }
    });
  }

  analyzeInvestmentData() {
    const dataSet = this.spreadsheet.dataSet;
    const originalData = dataSet.getDisplayDataSet();

    console.log('=== 投资分析报告 ===');

    data.forEach(item => {
      const returnAmount = item.investment * item.roi;
      const riskLevel = this.calculateRiskLevel(item.roi);

      console.log(`\n公司: ${item.company}`);
      console.log(`部门: ${item.department}`);
      console.log(`投资金额: ¥${item.investment.toLocaleString()}`);
      console.log(`投资回报率: ${(item.roi * 100).toFixed(2)}%`);
      console.log(`预期回报金额: ¥${returnAmount.toLocaleString()}`);
      console.log(`风险等级: ${riskLevel}`);
    });
  }

  calculateRiskLevel(roi) {
    if (roi >= 0.2) return '低风险 - 高回报';
    if (roi >= 0.15) return '中低风险 - 良好回报';
    if (roi >= 0.1) return '中等风险 - 一般回报';
    if (roi >= 0.05) return '中高风险 - 较低回报';
    return '高风险 - 低回报';
  }

  generateRiskAssessment(meta) {
    const data = meta.data;
    const roi = data.roi;
    const investment = data.investment;

    console.log('\n=== 详细风险评估 ===');
    console.log(`评估对象: ${data.company} - ${data.department}`);
    console.log(`投资建议: ${this.getInvestmentAdvice(roi)}`);
    console.log(`资金安全性: ${this.getSecurityLevel(investment)}`);
    console.log(`市场前景: ${this.getMarketOutlook(data.department)}`);
  }

  getInvestmentAdvice(roi) {
    if (roi >= 0.15) return '推荐投资 - 预期回报优秀';
    if (roi >= 0.1) return '谨慎投资 - 需要进一步评估';
    return '不建议投资 - 风险过高';
  }

  getSecurityLevel(investment) {
    if (investment <= 1000000) return '低风险投资额度';
    if (investment <= 2000000) return '中等风险投资额度';
    return '高风险投资额度，需要董事会审批';
  }

  getMarketOutlook(department) {
    const outlookMap = {
      'AI部门': '市场前景广阔，技术发展迅速',
      '自动化部门': '传统行业转型，稳定增长',
      '新能源部门': '政策支持，高成长性',
      '生物医药部门': '长期投资，高风险高回报'
    };
    return outlookMap[department] || '需要进一步市场调研';
  }
}

