import { PivotSheet, S2Event, BaseEvent } from '@antv/s2';

class CustomHoverInteraction extends BaseEvent {
  bindEvents() {
    this.spreadsheet.on(S2Event.DATA_CELL_HOVER, (event) => {
      const cell = this.spreadsheet.getCell(event.target);
      const meta = cell?.getMeta();

      if (meta && meta.valueField === 'gmv') {
        const platform = meta.rowQuery?.platform || '未知平台';
        const channel = meta.rowQuery?.channel || '未知渠道';
        const gmv = meta.fieldValue;

        this.spreadsheet.tooltip.show({
          position: {
            x: event.clientX,
            y: event.clientY,
          },
          content: `
            <div style="padding: 8px; background: #fff; border: 1px solid #d9d9d9; border-radius: 4px; box-shadow: 0 2px 8px rgba(0,0,0,0.15);">
              <div><strong>平台信息</strong></div>
              <div>渠道: ${channel}</div>
              <div>平台: ${platform}</div>
              <div>GMV: ${Number(gmv).toLocaleString()} 元</div>
            </div>
          `,
        });
      }
    });
  }
}

