import { PivotSheet, RowCell, DataCell } from '@antv/s2';
import { Circle } from '@antv/g';

// 自定义行头单元格
class CustomRowCell extends RowCell {
  getBackgroundColor() {
    const meta = this.getMeta();
    const region = meta.value;

    const regionColors = {
      '华北': '#E6F7FF',
      '华南': '#F6FFED'
    };

    return regionColors[region] || super.getBackgroundColor();
  }

  drawBackgroundShape() {
    this.backgroundShape = this.addShape('rect', {
      attrs: {
        ...this.getBBoxByType(),
        fill: this.getBackgroundColor(),
        stroke: this.getStyle().cell?.horizontalBorderColor,
        lineWidth: this.getStyle().cell?.horizontalBorderWidth,
      },
    });
  }
}

// 自定义数值单元格
class CustomDataCell extends DataCell {
  drawTextShape() {
    super.drawTextShape();

    // 添加自定义图标
    const bbox = this.getBBoxByType();
    this.appendChild(
      new Circle({
        style: {
          cx: bbox.x + bbox.width - 15,
          cy: bbox.y + 15,
          r: 5,
          fill: '#1890ff',
        },
      })
    );
  }
}

